//! Repairs the zsh script generated by `clap_complete`.
//!
//! When a command has both positional arguments and subcommands, `clap_complete`
//! writes the positionals *and* the subcommand dispatch into the same
//! `_arguments` call:
//!
//! ```text
//! '*::directory -- The directories or files to list:_files' \
//! ":: :_lla_commands" \
//! "*::: :->lla" \
//! ```
//!
//! zsh only allows one rest (`*:`) spec per `_arguments` call, so every
//! completion attempt fails with `doubled rest argument definition`
//! (clap-rs/clap#3022). Even without a rest positional, the subcommand slot
//! sits after the positionals, so subcommands are never offered first.
//!
//! The fix applied here, per affected `_arguments` call:
//!
//! - the positional specs are removed and the first positional's completion is
//!   offered next to the subcommands in the first slot (via `_alternative`),
//!   which becomes required so the rest spec starts at the second word;
//! - the dispatch reads the command word from `$line[1]`;
//! - a fallback `(*)` branch is added to the dispatch, so when the first word is
//!   not a subcommand the remaining options and positionals still complete.

const ARGUMENTS_START: &str = "_arguments \"${_arguments_options[@]}\" \\";
const ARGUMENTS_END: &str = "&& ret=0";

pub fn fix_zsh_completion(script: &str) -> String {
    let mut lines: Vec<String> = script.lines().map(String::from).collect();

    let mut i = 0;
    while i < lines.len() {
        if lines[i].trim() == ARGUMENTS_START {
            if let Some(end) = find_line(&lines, i + 1, |l| l.trim() == ARGUMENTS_END) {
                fix_arguments_block(&mut lines, i, end);
            }
        }
        i += 1;
    }

    let mut fixed = lines.join("\n");
    if script.ends_with('\n') {
        fixed.push('\n');
    }
    fixed
}

fn fix_arguments_block(lines: &mut Vec<String>, start: usize, end: usize) {
    let body = start + 1..end;

    let Some(commands_idx) = body.clone().find(|&j| is_commands_spec(&lines[j])) else {
        return;
    };
    let Some(state) = lines
        .get(commands_idx + 1)
        .and_then(|l| state_name(l))
        .map(String::from)
    else {
        return;
    };
    let positionals: Vec<usize> = body.clone().filter(|&j| is_positional(&lines[j])).collect();
    if positionals.is_empty() {
        return;
    }

    // The dispatch generated for this block: `case $state in (state) ... case $line[N] in ... esac`.
    let dispatch_pos = format!("({})", state);
    let Some(state_idx) = find_line(lines, end + 1, |l| l.trim() == dispatch_pos) else {
        return;
    };
    let Some(case_idx) = find_line(lines, state_idx + 1, |l| {
        let t = l.trim();
        t.starts_with("case $line[") && t.ends_with(" in")
    }) else {
        return;
    };
    let Some(esac_idx) = matching_esac(lines, case_idx) else {
        return;
    };
    let line_ref = lines[case_idx]
        .trim()
        .trim_start_matches("case ")
        .trim_end_matches(" in")
        .to_string();

    // Fallback branch: the first word was not a subcommand, so complete what
    // can follow it. The first positional was consumed by that word, unless it
    // is a rest argument, which also covers the following words.
    let first = positionals[0];
    let mut fallback = vec!["(*)".to_string(), ARGUMENTS_START.to_string()];
    for j in body.clone() {
        if j == commands_idx || j == commands_idx + 1 {
            continue;
        }
        if j == first && !is_rest_positional(&lines[j]) {
            continue;
        }
        fallback.push(lines[j].clone());
    }
    fallback.push(ARGUMENTS_END.to_string());
    fallback.push(";;".to_string());

    // The first slot offers the subcommands next to the first positional's
    // completion. It is made required (`:` instead of `::`) so the rest spec
    // only starts at the second word: otherwise zsh also enters the dispatch,
    // and so the fallback, while the first word is still being typed.
    let function = lines[commands_idx]
        .trim()
        .trim_start_matches("\":: :")
        .trim_end_matches("\" \\")
        .to_string();
    let action = match positional_action(&lines[first]) {
        Some(action) => format!(
            "{{_alternative 'commands:command:{}' 'args:argument:{}'}}",
            function, action
        ),
        None => function,
    };
    lines[commands_idx] = format!("\": :{}\" \\", action);

    // Apply from the bottom up so earlier indices stay valid.
    lines.splice(esac_idx..esac_idx, fallback);
    for line in &mut lines[state_idx..=case_idx] {
        *line = line.replace(&line_ref, "$line[1]");
    }
    for &j in positionals.iter().rev() {
        lines.remove(j);
    }
}

fn find_line(lines: &[String], from: usize, pred: impl Fn(&str) -> bool) -> Option<usize> {
    (from..lines.len()).find(|&j| pred(&lines[j]))
}

fn matching_esac(lines: &[String], case_idx: usize) -> Option<usize> {
    let mut depth = 0usize;
    for (j, line) in lines.iter().enumerate().skip(case_idx) {
        let t = line.trim();
        if t.starts_with("case ") && t.ends_with(" in") {
            depth += 1;
        } else if t == "esac" {
            depth -= 1;
            if depth == 0 {
                return Some(j);
            }
        }
    }
    None
}

/// `":: :_lla_commands" \`
fn is_commands_spec(line: &str) -> bool {
    let t = line.trim();
    t.starts_with("\":: :_") && t.ends_with("_commands\" \\")
}

/// `"*::: :->lla" \` → `lla`
fn state_name(line: &str) -> Option<&str> {
    line.trim()
        .strip_prefix("\"*::: :->")?
        .strip_suffix("\" \\")
}

/// `':name -- help:action' \`, `'::name...'` or `'*::name...'`; options start with `-`, `(` or `*-`.
fn is_positional(line: &str) -> bool {
    let t = line.trim();
    t.starts_with("':") || t.starts_with("'*:")
}

fn is_rest_positional(line: &str) -> bool {
    line.trim().starts_with("'*:")
}

/// The completion action of a positional spec, if it has a simple one.
fn positional_action(line: &str) -> Option<String> {
    let spec = line.trim().strip_prefix('\'')?.strip_suffix("' \\")?;
    // The action follows the last colon that is not escaped in the help text.
    let bytes = spec.as_bytes();
    let colon = (0..bytes.len())
        .rev()
        .find(|&k| bytes[k] == b':' && (k == 0 || bytes[k - 1] != b'\\'))?;
    let action = spec[colon + 1..].trim();
    let simple = !action.is_empty()
        && !action
            .chars()
            .any(|c| matches!(c, '\'' | '"' | '$' | '`' | '\\' | '{' | '}'));
    simple.then(|| action.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::args::Args;
    use crate::config::Config;

    fn generated() -> String {
        let config = Config::default();
        let mut app = Args::get_cli(&config);
        let mut buf = Vec::new();
        clap_complete::generate(clap_complete::Shell::Zsh, &mut app, "lla", &mut buf);
        String::from_utf8(buf).unwrap()
    }

    /// Every `_arguments` call, as its list of spec lines.
    fn argument_blocks(script: &str) -> Vec<Vec<&str>> {
        let mut blocks = Vec::new();
        let mut current: Option<Vec<&str>> = None;
        for line in script.lines() {
            let t = line.trim();
            if t == ARGUMENTS_START {
                current = Some(Vec::new());
            } else if t == ARGUMENTS_END {
                blocks.extend(current.take());
            } else if let Some(block) = current.as_mut() {
                block.push(t);
            }
        }
        blocks
    }

    #[test]
    fn unpatched_script_has_the_bug() {
        // Guards the test below: if clap_complete stops emitting doubled rest
        // specs, this post-processing can be dropped.
        let doubled = argument_blocks(&generated()).iter().any(|b| {
            b.iter()
                .filter(|l| l.starts_with("'*:") || l.starts_with("\"*:"))
                .count()
                > 1
        });
        assert!(doubled);
    }

    #[test]
    fn at_most_one_rest_spec_per_arguments_call() {
        let fixed = fix_zsh_completion(&generated());
        for block in argument_blocks(&fixed) {
            let rest = block
                .iter()
                .filter(|l| l.starts_with("'*:") || l.starts_with("\"*:"))
                .count();
            assert!(rest <= 1, "doubled rest spec in:\n{}", block.join("\n"));
        }
    }

    #[test]
    fn subcommands_dispatch_from_the_first_word() {
        let fixed = fix_zsh_completion(&generated());
        assert!(fixed.contains(concat!(
            "\": :{_alternative 'commands:command:_lla_commands' 'args:argument:_files'}\" \\\n",
            "\"*::: :->lla\" \\\n",
            "&& ret=0",
        )));
        assert!(fixed.contains("\": :_lla__plugin_commands\" \\\n\"*::: :->plugin\" \\"));
        assert!(fixed.contains("curcontext=\"${curcontext%:*:*}:lla-command-$line[1]:\""));
        assert!(fixed.contains("curcontext=\"${curcontext%:*:*}:lla-plugin-command-$line[1]:\""));
        assert!(!fixed.contains("$line[2]"));
        assert!(!fixed.contains("$line[4]"));
    }

    #[test]
    fn positionals_still_complete_after_a_non_subcommand_word() {
        let fixed = fix_zsh_completion(&generated());
        // Top level: more paths, plus the options.
        let top = fixed.rfind("(*)\n").expect("top-level fallback");
        let top = &fixed[top..fixed[top..].find(";;").unwrap() + top];
        assert!(top.contains("'--tree[Use tree listing format (overrides config format)]' \\"));
        assert!(top.contains("'*::directory -- The directories or files to list:_files' \\"));
        // `lla plugin <name>`: the action and its arguments, but not the name again.
        assert!(fixed.contains(concat!(
            "'::plugin_action -- Action to perform:' \\\n",
            "'*::plugin_args -- Arguments for the plugin action:' \\\n",
            "&& ret=0\n",
            ";;\n",
        )));
        assert_eq!(fixed.matches("::plugin_name").count(), 0);
    }

    #[test]
    fn leaves_scripts_without_the_pattern_alone() {
        let script = "_arguments \"${_arguments_options[@]}\" \\\n'-h[Print help]' \\\n':path:' \\\n&& ret=0\n";
        assert_eq!(fix_zsh_completion(script), script);
    }
}
